/// `MO(layer)` → layer, as decoded by `action_for_keycode()`.
pub fn mo_layer(kc: u16) -> Option<usize> {
    if (QK_MOMENTARY..=QK_MOMENTARY_MAX).contains(&kc) { Some((kc & 0x1F) as usize) } else { None }
}

/// `IS_CONSUMER_KEYCODE()`.
pub fn is_consumer_key(kc: u16) -> bool {
    (KC_AUDIO_MUTE..=KC_LAUNCHPAD).contains(&kc)
}

/// `IS_SYSTEM_KEYCODE()`.
pub fn is_system_key(kc: u16) -> bool {
    (KC_SYSTEM_POWER..=KC_SYSTEM_WAKE).contains(&kc)
}

/// `KEYCODE2CONSUMER()`.
pub fn consumer_usage(kc: u16) -> u16 {
    match kc {
        0x00A8 => 0x00E2,
        0x00A9 => 0x00E9,
        0x00AA => 0x00EA,
        0x00AB => 0x00B5,
        0x00AC => 0x00B6,
        0x00BB => 0x00B3,
        0x00BC => 0x00B4,
        0x00AD => 0x00B7,
        0x00B0 => 0x00CC,
        0x00AE => 0x00CD,
        0x00AF => 0x0183,
        0x00B1 => 0x018A,
        0x00B2 => 0x0192,
        0x00B3 => 0x0194,
        0x00BF => 0x019F,
        0x00C0 => 0x01CB,
        0x00B4 => 0x0221,
        0x00B5 => 0x0223,
        0x00B6 => 0x0224,
        0x00B7 => 0x0225,
        0x00B8 => 0x0226,
        0x00B9 => 0x0227,
        0x00BD => 0x006F,
        0x00BE => 0x0070,
        0x00BA => 0x022A,
        0x00C1 => 0x029F,
        0x00C2 => 0x02A0,
        _ => 0,
    }
}

/// `KEYCODE2SYSTEM()`.
pub fn system_usage(kc: u16) -> u16 {
    match kc {
        0x00A5 => 0x0081,
        0x00A6 => 0x0082,
        0x00A7 => 0x0083,
        _ => 0,
    }
}

