/// `keycode_at_keymap_location_raw()`: KC_TRNS beyond the compiled layers.
pub fn get_keycode(layer: usize, row: usize, col: usize) -> u16 {
    if row < 6 && col < 21 && layer < LAYER_COUNT { KEYMAPS[layer][row][col] } else { KC_TRNS }
}
